entries[127823] = { ["name"] = "Unheilvoller Plattengürtel", ["text"] = "Wird an Kriegsmeute gebunden\nKlassen: Krieger , Paladin , Todesritter\nBenutzen: Erschafft einen seelengebundenen Gegenstand, der für Eure Beutespezialisierung nützlich ist.\nVerkaufspreis:" }
entries[127828] = { ["name"] = "Schillernde Rute", ["text"] = "Wird beim Aufheben gebunden\nWaffenhand\n1 Arkanschaden Geschwindigkeit 1.60\n(0.6 Schaden pro Sekunde)\nBenutzen: Feuert eine schnelle Kugel aus arkaner Energie ab.\n\nKann nur Spielercharaktere treffen, die eine schillernde Rute verwenden.\nVerkaufspreis:" }
entries[127829] = { ["name"] = "Zwillingsklingen des Betrügers", ["text"] = "Verus\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Kriegsgleve\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\n\nTeufel Artefakt Relikt Slot\nSchatten Artefakt Relikt Slot\n\nKlassen: Dämonenjäger\nAnlegen: Gewährt die Fähigkeit 'Zorn der Illidari', die alle Gegner in der Nähe wiederholt mit Euren Kriegsgleven aufschlitzt.\n\"Statuiert Exempel an jenen, die närrisch genug sind, sich Euch zu widersetzen, dann wird der Rest ihrer Art sich Euch zu Füßen werfen.\"\nVerkaufspreis:" }
entries[127830] = { ["name"] = "Zwillingsklingen des Betrügers", ["text"] = "Muramas\nWird beim Aufheben gebunden\nEinzigartig\nSchildhand Kriegsgleve\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\nKlassen: Dämonenjäger\n\"Das Ende ist gekommen! Lasst die Zerstörung dieser Welt beginnen!\"\nVerkaufspreis:" }
entries[127831] = { ["name"] = "Geldkassette des Herausforderers", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>\nVerkaufspreis:" }
entries[127833] = { ["name"] = "Schiff: Zerstörer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Ein mächtiges Schiff mit großen Kanonen. Kann auf Marinemissionen eingesetzt werden.\"" }
entries[127834] = { ["name"] = "Uralter Heiltrank", ["text"] = "Benutzen: Regeneriert 6000 Gesundheit. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[127835] = { ["name"] = "Uralter Manatrank", ["text"] = "Benutzen: Regeneriert 2000 Mana. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[127836] = { ["name"] = "Uralter Verjüngungstrank", ["text"] = "Benutzen: Regeneriert 6000 Gesundheit und 1500 Mana. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[127837] = { ["name"] = "Destillat aus roher Magie", ["text"] = "Benutzen: Auf ex.\nVerkaufspreis:" }
entries[127838] = { ["name"] = "Sylvanelixier", ["text"] = "Benutzen: Verwandelt Euch in einen Baum. Ihr und alle Spielercharaktere, die sich in Eurem Schatten ausruhen, werden gut erholt und alle Eure Werte um 10% erhöht.\nVerkaufspreis:" }
entries[127839] = { ["name"] = "Lawinenelixier", ["text"] = "Benutzen: Wenn Ihr eine lange Strecke fallt, verwandelt Ihr Euch in eine Lawine. Beim Auftreffen fügt Ihr allen Gegnern innerhalb von 5 Metern 1500 Schaden zu. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[127840] = { ["name"] = "Skaggldrynk", ["text"] = "Benutzen: Begebt Euch in das Geisterreich und werdet so für 18 Sek. unsichtbar. Funktioniert nicht über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[127841] = { ["name"] = "Himmelslauftrank", ["text"] = "Benutzen: Erhöht die Bewegungsgeschwindigkeit um 150% und lässt den Trinkenden in der Luft schweben. Hält 8 Sek. lang an. Funktioniert nicht über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[127842] = { ["name"] = "Infernaler Alchemistenstein", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+ 7 Vielseitigkeit\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 19 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie der Verheerten Inseln\n(1)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:" }
entries[127843] = { ["name"] = "Trank der tödlichen Anmut", ["text"] = "Benutzen: Gewährt Euren Angriffen eine Chance, einen Energieblitz auf Euer Ziel zu entfesseln.\n\nWenn Ihr Euch während der gesamten Effektdauer von Gegnern fernhaltet, wird sie um zusätzliche 5 Sek. verlängert. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[127844] = { ["name"] = "Trank des Alten Krieges", ["text"] = "Benutzen: Beschwört zwei geisterhafte gefallene Krieger, die an Eurer Seite kämpfen. Sie können Eure Nahkampfangriffe und -fähigkeiten imitieren und verursachen damit 1161 Schaden. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[127845] = { ["name"] = "Unbeugsamer Trank", ["text"] = "Benutzen: Erhöht Eure Rüstung 25 Sek. lang um 124 . (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[127846] = { ["name"] = "Leywirbeltrank", ["text"] = "Benutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu ( 300 * 10) Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[127847] = { ["name"] = "Fläschchen des geflüsterten Pakts", ["text"] = "Benutzen: Erhöht die Intelligenz 1 Stunde lang um 46 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[127848] = { ["name"] = "Fläschchen des Siebten Dämons", ["text"] = "Benutzen: Erhöht die Beweglichkeit 1 Stunde lang um 46 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[127849] = { ["name"] = "Fläschchen der zahllosen Armeen", ["text"] = "Benutzen: Erhöht die Stärke 1 Stunde lang um 46 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[127850] = { ["name"] = "Fläschchen der zehntausend Narben", ["text"] = "Benutzen: Erhöht die Ausdauer 1 Stunde lang um 69 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[127851] = { ["name"] = "Geisterkessel", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Stellt einen Kessel her, der von Schlachtzugsmitgliedern benutzt werden kann, um an ein Fläschchen entsprechend ihrer Klasse und ihren Talenten zu gelangen. Der Kessel hat 30 Anwendungen und bleibt 10 Min. lang bestehen.\nVerkaufspreis:" }
entries[127853] = { ["name"] = "Schatzkiste der Eisernen Flotte", ["text"] = "Normal\nWird beim Aufheben gebunden\n\"Enthält einen Gegenstand des Schwierigkeitsgrads 'Normal' aus der Schlachtzugzone Höllenfeuerzitadelle.\"\n<Zum Öffnen rechtsklicken>" }
entries[127854] = { ["name"] = "Schatzkiste der Eisernen Flotte", ["text"] = "Heroisch\nWird beim Aufheben gebunden\n\"Enthält einen Gegenstand des Schwierigkeitsgrads 'Heroisch' aus der Schlachtzugzone Höllenfeuerzitadelle.\"\n<Zum Öffnen rechtsklicken>" }
entries[127855] = { ["name"] = "Schatzkiste der Eisernen Flotte", ["text"] = "Mythisch\nWird beim Aufheben gebunden\n\"Enthält einen Gegenstand des Schwierigkeitsgrads 'Mythisch' aus der Schlachtzugzone Höllenfeuerzitadelle.\"\n<Zum Öffnen rechtsklicken>" }
entries[127856] = { ["name"] = "Zurückgelassener Hai", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren zurückgelassenen Hai beschwören oder wieder freigeben.\n80 ( 80)" }
entries[127857] = { ["name"] = "Aluneth", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n2 - 3 Schaden Geschwindigkeit 3.60\n(0.7 Schaden pro Sekunde)\n+9 Intelligenz\n+3 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nArkan Artefakt Relikt Slot\nFrost Artefakt Relikt Slot\n\nKlassen: Magier\nAnlegen: Gewährt die Fähigkeit 'Mal von Aluneth', die eine Rune auf dem Boden platziert, die nach kurzer Zeit explodiert und massiven Schaden verursacht.\n\"Nach vielen Rückschlägen schaffte Aegwynn es endlich, das Wesen an einen verzauberten Großstab zu binden. Die Aufgabe, Aluneth einzugrenzen, war somit vollbracht, doch die Wächterin brauchte noch Jahre, bis sie die Macht wirklich nutzen konnte.\"\nVerkaufspreis:" }
entries[127858] = { ["name"] = "Geisterfläschchen", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig: Gildenfläschchen (1)\nBenutzen: Gewährt den Effekt eines Fläschchens basierend auf Eurer Klasse und Euren Talenten. Hält 1 Stunde lang und über den Tod hinaus an. (3 Sek. Abklingzeit)" }
entries[127859] = { ["name"] = "Schillernde Rute", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Rüstet Euch mit einer schillernden Rute aus, die es Euch gestattet, arkane Energie auf andere abzufeuern, die diese Rute ebenfalls tragen. (5 Sek. Abklingzeit)\n\"Ein beliebtes Spielzeug unter Draeneikindern.\"" }
entries[127860] = { ["name"] = "Signet des Wächters", ["text"] = "Val'sharah\nWird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Die Zeit hat ihre Spuren hinterlassen.\"" }
entries[127861] = { ["name"] = "Höhlenpilzstuhl", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt einen leuchtenden Pilzstuhl auf. (5 Min Abklingzeit)" }
entries[127863] = { ["name"] = "Gefängnisschlüssel", ["text"] = "Questgegenstand\n\"Ein Satz länglicher, skelettartiger Schlüssel baumelt an einer Silberkette.\"" }
entries[127864] = { ["name"] = "Persönliches Rampenlicht", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Platziert einen Scheinwerfer über Eurem Kopf. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[127865] = { ["name"] = "Ein klitzekleiner Wikingerhelm", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Wenn Pepe beschworen wird, ist er manchmal gekleidet wie ein Wikinger." }
entries[127866] = { ["name"] = "REUSEME", ["text"] = "Wird beim Aufheben gebunden" }
entries[127867] = { ["name"] = "Ein klitzekleiner Ninjamantel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Wenn Pepe beschworen wird, ist er manchmal gekleidet wie ein Ninja." }
entries[127868] = { ["name"] = "Zermalmer", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Zermalmer beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[127869] = { ["name"] = "Ein klitzekleiner Plattenhelm", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Wenn Pepe beschworen wird, ist er manchmal gekleidet wie ein Ritter." }
entries[127870] = { ["name"] = "Ein klitzekleiner Piratenhut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Wenn Pepe beschworen wird, ist er manchmal gekleidet wie ein Pirat." }
entries[127871] = { ["name"] = "Ausgebrannter Leyflammenbrenner", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieser Brenner war einst in der Lage, eine starke Flamme aus Leyenergie hervorzubringen, die in der Alchemie sehr nützlich ist.\"\nVerkaufspreis:" }
entries[127872] = { ["name"] = "Gesprungenes zweikammeriges Mischfläschchen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Der Sprung in diesem einstmals wertvollen Mischbehälter macht ihn für die Alchemie nutzlos.\"" }
entries[127873] = { ["name"] = "Verbesserte Korken", ["text"] = "Questgegenstand\nEinzigartig\n\"Diese dichten Korken sehen so aus, als ob sie in der Lage wären, instabile Mixturen gut verschließen zu können.\"" }
entries[127874] = { ["name"] = "Präzipitationspulver", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieses Pulver wurde aus den Ascherückständen hergestellt, die der Atem eines Drachen hinterließ, und dürfte in der Alchemie äußerst nützlich sein.\"" }
entries[127875] = { ["name"] = "Seidenfilter der Shal'dorei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Wenn dieser Stoff nicht zerrissen wäre, könnte man ihn hervorragend zum Filtern von alchemistischen Flüssigkeiten benutzen.\"" }
entries[127876] = { ["name"] = "Brüchiger Dämonenodemtiegel", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieser Topf wurde hergestellt, um darin mächtige Teufelsreagenzien zusammenzumischen, aber er muss wohl ein wenig verstärkt werden.\"" }
entries[127877] = { ["name"] = "Biegsame Glasröhren", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Beständige Röhren, ideal für den Transport von alchemistischen Reagenzien.\"" }
entries[127878] = { ["name"] = "Unkalibrierte Mallorybürette", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Mit dieser Bürette kann man Flüssigkeiten nicht genau abmessen.\"" }
entries[127879] = { ["name"] = "Leistungsstarker Sudkatalysator", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[127880] = { ["name"] = "Eisbrecher", ["text"] = "Marineausstattung\nWird beim Aufheben gebunden\nBenutzen: Rüstet ein Kriegsschiff mit einem Eisbrecher aus.\n\nKontert:\nEisiges Wasser\nBenötigt Ausstattungsbaupläne, die zuletzt in der Nähe der Eisendocks gesehen wurden.\nVerkaufspreis:" }
entries[127881] = { ["name"] = "Interner Gyrostabilisator", ["text"] = "Marineausstattung\nWird beim Aufheben gebunden\nBenutzen: Rüstet ein Kriegsschiff mit einem internen Gyrostabilisator aus.\n\nKontert:\nChaotische Strudel\nBenötigt Ausstattungsbaupläne, die zuletzt in der Höllenfeuerzitadelle gesehen wurden.\nVerkaufspreis:" }
entries[127882] = { ["name"] = "Heizkessel", ["text"] = "Marineausstattung\nWird beim Aufheben gebunden\nBenutzen: Rüstet ein Kriegsschiff mit einem Heizkessel aus.\n\nKontert:\nSchnell\nBenötigt Ausstattungsbaupläne: Heizkessel." }
entries[127883] = { ["name"] = "Echteisenruder", ["text"] = "Marineausstattung\nWird beim Aufheben gebunden\nBenutzen: Rüstet ein Kriegsschiff mit einem Echteisenruder aus.\n\nKontert:\nWendig\nBenötigt Ausstattungsbaupläne, die zuletzt in den Eisendocks gesehen wurden.\nVerkaufspreis:" }
entries[127884] = { ["name"] = "Teufelsrauchwerfer", ["text"] = "Marineausstattung\nWird beim Aufheben gebunden\nBenutzen: Rüstet ein Kriegsschiff mit Teufelsrauchwerfern aus.\n\nKontert:\nErstschlag\nBenötigt Ausstattungsbaupläne, die zuletzt in der Nähe der Dämonenschmiede gesehen wurden.\nVerkaufspreis:" }
entries[127885] = { ["name"] = "Raubeinige Besatzung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Heuert eine raubeinige Besatzung für Euer Kriegsschiff an.\n\"Diese Besatzung hat schon alles erlebt – wie man an ihren Hüten erkennen kann. Erhöht die Erfolgschance für Missionen um 10%.\"" }
entries[127886] = { ["name"] = "Unsinkbar", ["text"] = "Marineausstattung\nWird beim Aufheben gebunden\nBenutzen: Stattet ein Schiff mit 'Unsinkbar' aus.\n\nBei einem vernichtenden Treffer wird das Schiff vor dem Sinken gerettet, indem es in einen undurchdringlichen Schild gehüllt wird. 'Unsinkbar' wird beim Auslösen zerstört.\nBenötigt Ausstattungsbaupläne, die zuletzt im Besitz eines Händlers im Tanaandschungel gesehen wurden.\nVerkaufspreis:" }
entries[127887] = { ["name"] = "Nahrungsvorrat", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Rüstet ein Kriegsschiff mit Nahrungsvorräten aus.\n\"Schafft Platz für zusätzlichen Proviant, wodurch sich die Moral und die Erfolgschance auf langen Törns erhöhen.\"" }
entries[127888] = { ["name"] = "Automatischer Himmelsscanner", ["text"] = "Marineausstattung\nWird beim Aufheben gebunden\nBenutzen: Rüstet ein Kriegsschiff mit einem automatischen Himmelsscanner aus.\n\nUnterstützung: Trägerschiff\nVerkaufspreis:" }
entries[127889] = { ["name"] = "Munitionsreserven", ["text"] = "Marineausstattung\nWird beim Aufheben gebunden\nBenutzen: Rüstet ein Kriegsschiff mit Munitionsreserven aus.\n\nUnterstützung: Schlachtschiff\nVerkaufspreis:" }
entries[127890] = { ["name"] = "Schallverstärkerfeld", ["text"] = "Marineausstattung\nWird beim Aufheben gebunden\nBenutzen: Rüstet ein Kriegsschiff mit einem Schallverstärkerfeld aus.\n\nUnterstützung: Zerstörer\nVerkaufspreis:" }
entries[127891] = { ["name"] = "Zusätzliche Kojen", ["text"] = "Marineausstattung\nWird beim Aufheben gebunden\nBenutzen: Rüstet ein Kriegsschiff mit zusätzlichen Kojen aus.\n\nUnterstützung: Transporter\nVerkaufspreis:" }
entries[127892] = { ["name"] = "Q43-Radaumacherminen", ["text"] = "Marineausstattung\nWird beim Aufheben gebunden\nBenutzen: Rüstet ein Kriegsschiff mit Q43-Radaumacherminen aus.\n\nUnterstützung: U-Boot\nVerkaufspreis:" }
entries[127893] = { ["name"] = "Wrackbergungsmodul", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Rüstet ein Kriegsschiff mit einem Wrackbergungsmodul aus.\n\"Beim Einsatz während einer erfolgreichen Mission filtert dieses Gerät das Umgebungsgewässer und birgt eine Kiste voll nützlichem Kram.\"" }
entries[127894] = { ["name"] = "Tuskarrfischernetz", ["text"] = "Marineausstattung\nWird beim Aufheben gebunden\nBenutzen: Rüstet ein Kriegsschiff mit einem Tuskarrfischernetz aus.\n\nEin Fischernetz der Tuskarr, das am Heck angebracht ist. Fängt Fische und liefert sie bei erfolgreichem Abschluss der Mission ab.\nBenötigt Ausstattungsbaupläne, die zuletzt im Besitz eines Händlers im Tanaandschungel gesehen wurden.\nVerkaufspreis:" }
entries[127895] = { ["name"] = "Geisterhaftes Fernglas", ["text"] = "Marineausstattung\nWird beim Aufheben gebunden\nBenutzen: Rüstet ein Kriegsschiff mit einem geisterhaften Fernglas aus.\n\nEin langes Fernglas, das Euch nichts zeigt, wenn Ihr hindurchblickt. Vielleicht erweist es sich doch noch als nützlich.\nBenötigt Ausstattungsbaupläne: Geisterhaftes Fernglas.\nVerkaufspreis:" }
entries[127896] = { ["name"] = "Nitrotanks", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Rüstet ein Kriegsschiff mit Nitrotanks aus.\n\"Ermöglicht es einem Schiff, Nitrotreibstoff zu verbrennen, wodurch es sein Ziel schneller erreichen kann.\"" }
entries[127897] = { ["name"] = "Das Schwert der Wahrheit", ["text"] = "Questgegenstand\nBenutzen: Stoßt Rabenkrones Schwert am ausgewählten Ort in den Boden. (3 Sek. Abklingzeit)\n\"Aus einer dicken Schicht Schmutz und Schmodder glänzt die Klinge hervor.\"" }
entries[127898] = { ["name"] = "Rezept: Uralter Heiltrank", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung eines uralten Heiltranks.\nStellt einen uralten Heiltrank an der Dalaraner Alchemiestation her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nUralter Heiltrank\nBenutzen: Regeneriert 6000 Gesundheit. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Yserallinensamen (4), Kristallphiole" }
entries[127899] = { ["name"] = "Rezept: Uralter Manatrank", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung eines uralten Manatranks.\nStellt einen uralten Manatrank an der Dalaraner Alchemiestation her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nUralter Manatrank\nBenutzen: Regeneriert 2000 Mana. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Yserallinensamen (5), Kristallphiole" }
entries[127900] = { ["name"] = "Rezept: Uralter Verjüngungstrank", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung eines uralten Verjüngungstranks.\nStellt einen uralten Verjüngungstrank an der Dalaraner Alchemiestation her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nUralter Verjüngungstrank\nBenutzen: Regeneriert 6000 Gesundheit und 1500 Mana. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Uralter Heiltrank , Uralter Manatrank" }
entries[127901] = { ["name"] = "Rezept: Destillat aus roher Magie", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Destillat aus roher Magie herstellt.\nStellt ein Destillat aus roher Magie an der Dalaraner Alchemiestation her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nBenötigt Leyflammenbrenner\nVerkaufspreis:\nDestillat aus roher Magie\nBenutzen: Auf ex.\nVerkaufspreis:\nBenötigt Aethril (20), Uralter Heiltrank" }
entries[127902] = { ["name"] = "Rezept: Sylvanelixier", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Sylvanelixier herstellt.\nStellt ein Sylvanelixier an der Dalaraner Alchemiestation her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nBenötigt verbesserte Korken\nVerkaufspreis:\nSylvanelixier\nBenutzen: Verwandelt Euch in einen Baum. Ihr und alle Spielercharaktere, die sich in Eurem Schatten ausruhen, werden gut erholt und alle Eure Werte um 10% erhöht.\nVerkaufspreis:\nBenötigt Traumlaub (5), Uralter Heiltrank" }
entries[127903] = { ["name"] = "Rezept: Lawinenelixier", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Lawinenelixier herstellt.\nStellt ein Lawinenelixier an der Dalaraner Alchemiestation her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nBenötigt zweikammeriges Mischfläschchen\nVerkaufspreis:\nLawinenelixier\nBenutzen: Wenn Ihr eine lange Strecke fallt, verwandelt Ihr Euch in eine Lawine. Beim Auftreffen fügt Ihr allen Gegnern innerhalb von 5 Metern 1500 Schaden zu. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Fuchsblume (5), Uralter Manatrank" }
entries[127904] = { ["name"] = "Rezept: Skaggldrynk", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Skaggldrynk herstellt.\nStellt einen Skaggldrynk an der Dalaraner Alchemiestation her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nBenötigt Präzipitationspulver\nVerkaufspreis:\nSkaggldrynk\nBenutzen: Begebt Euch in das Geisterreich und werdet so für 18 Sek. unsichtbar. Funktioniert nicht über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Fjarnskaggl (5), Uralter Manatrank" }
entries[127905] = { ["name"] = "Rezept: Himmelslauftrank", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Himmelslauftrank herstellt.\nStellt einen Himmelslauftrank an der Dalaraner Alchemiestation her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nBenötigt Seidenfilter der Shal'dorei\nVerkaufspreis:\nHimmelslauftrank\nBenutzen: Erhöht die Bewegungsgeschwindigkeit um 150% und lässt den Trinkenden in der Luft schweben. Hält 8 Sek. lang an. Funktioniert nicht über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose (4), Uralter Verjüngungstrank" }
entries[127906] = { ["name"] = "Rezept: Infernaler Alchemistenstein", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen infernalen Alchemistenstein herstellt.\nStellt einen infernalen Alchemistenstein an der Dalaraner Alchemiestation her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nBenötigt Dämonenodemtiegel\nVerkaufspreis:\nInfernaler Alchemistenstein\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+ 7 Vielseitigkeit\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 19 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie der Verheerten Inseln\n(1)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:\nBenötigt Infernoschwefel , Teufelswurz (5), Blut von Sargeras (3)" }
entries[127907] = { ["name"] = "Rezept: Trank der tödlichen Anmut", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Trank der tödlichen Anmut herstellt.\nStellt einen Trank der tödlichen Anmut an der Dalaraner Alchemiestation her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nBenötigt verbesserte Korken, biegsame Glasröhren und Seidenfilter der Shal'dorei.\nVerkaufspreis:\nTrank der tödlichen Anmut\nBenutzen: Gewährt Euren Angriffen eine Chance, einen Energieblitz auf Euer Ziel zu entfesseln.\n\nWenn Ihr Euch während der gesamten Effektdauer von Gegnern fernhaltet, wird sie um zusätzliche 5 Sek. verlängert. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose , Fjarnskaggl (2), Traumlaub (2), Kristallphiole" }
entries[127908] = { ["name"] = "Rezept: Trank des Alten Krieges", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Trank des Alten Krieges herstellt.\nStellt einen Trank des Alten Krieges an der Dalaraner Alchemiestation her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nBenötigt verbesserte Korken, biegsame Glasröhren und Präzipitationspulver.\nVerkaufspreis:\nTrank des Alten Krieges\nBenutzen: Beschwört zwei geisterhafte gefallene Krieger, die an Eurer Seite kämpfen. Sie können Eure Nahkampfangriffe und -fähigkeiten imitieren und verursachen damit 1161 Schaden. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose , Fuchsblume (2), Fjarnskaggl (2), Kristallphiole" }
entries[127909] = { ["name"] = "Rezept: Unbeugsamer Trank", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen unbeugsamen Trank herstellt.\nStellt einen unbeugsamen Trank an der Dalaraner Alchemiestation her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nBenötigt verbesserte Korken, biegsame Glasröhren und zweikammeriges Mischfläschchen.\nVerkaufspreis:\nUnbeugsamer Trank\nBenutzen: Erhöht Eure Rüstung 25 Sek. lang um 124 . (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose , Aethril (2), Fuchsblume (2), Kristallphiole" }
entries[127910] = { ["name"] = "Rezept: Leywirbeltrank", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Leywirbeltrank herstellt.\nStellt einen Leywirbeltrank an der Dalaraner Alchemiestation her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nBenötigt verbesserte Korken, biegsame Glasröhren und Leyflammenbrenner.\nVerkaufspreis:\nLeywirbeltrank\nBenutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu ( 300 * 10) Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose , Aethril (2), Traumlaub (2), Kristallphiole" }
entries[127911] = { ["name"] = "Rezept: Fläschchen des geflüsterten Pakts", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Fläschchen des geflüsterten Pakts herstellt.\nStellt ein Fläschchen des geflüsterten Pakts an der Dalaraner Alchemiestation her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nBenötigt Dämonenodemtiegel, Mallorybürettenaufbau und Seidenfilter der Shal'dorei.\nVerkaufspreis:\nFläschchen des geflüsterten Pakts\nBenutzen: Erhöht die Intelligenz 1 Stunde lang um 46 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose (7), Fjarnskaggl (10), Traumlaub (10), Kristallphiole" }
entries[127912] = { ["name"] = "Rezept: Fläschchen des Siebten Dämons", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Fläschchen des Siebten Dämons herstellt.\nStellt ein Fläschchen des Siebten Dämons an der Dalaraner Alchemiestation her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nBenötigt Dämonenodemtiegel, Mallorybürettenaufbau und Präzipitationspulver.\nVerkaufspreis:\nFläschchen des Siebten Dämons\nBenutzen: Erhöht die Beweglichkeit 1 Stunde lang um 46 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose (7), Fuchsblume (10), Fjarnskaggl (10), Kristallphiole" }
entries[127913] = { ["name"] = "Rezept: Fläschchen der zahllosen Armeen", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Fläschchen der zahllosen Armeen herstellt.\nStellt ein Fläschchen der zahllosen Armeen an der Dalaraner Alchemiestation her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nBenötigt Dämonenodemtiegel, Mallorybürettenaufbau und zweikammeriges Mischfläschchen.\nVerkaufspreis:\nFläschchen der zahllosen Armeen\nBenutzen: Erhöht die Stärke 1 Stunde lang um 46 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose (7), Aethril (10), Fuchsblume (10), Kristallphiole" }
entries[127914] = { ["name"] = "Rezept: Fläschchen der zehntausend Narben", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Fläschchen der zehntausend Narben herstellt.\nStellt ein Fläschchen der zehntausend Narben an der Dalaraner Alchemiestation her.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nBenötigt Dämonenodemtiegel, Mallorybürettenaufbau und Leyflammenbrenner.\nVerkaufspreis:\nFläschchen der zehntausend Narben\nBenutzen: Erhöht die Ausdauer 1 Stunde lang um 69 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose (7), Aethril (10), Traumlaub (10), Kristallphiole" }
entries[127915] = { ["name"] = "Rezept: Geisterkessel", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Geisterkessel herstellt.\nStellt einen Geisterkessel an der Dalaraner Alchemiestation her.\nBenötigt Alchemie der Verheerten Inseln\n(100)\nBenötigt leistungsstarken Sudkatalysator\nVerkaufspreis:\nGeisterkessel\nWird an Kriegsmeute gebunden\nBenutzen: Stellt einen Kessel her, der von Schlachtzugsmitgliedern benutzt werden kann, um an ein Fläschchen entsprechend ihrer Klasse und ihren Talenten zu gelangen. Der Kessel hat 30 Anwendungen und bleibt 10 Min. lang bestehen.\nVerkaufspreis:\nBenötigt Fläschchen des geflüsterten Pakts (5), Fläschchen des Siebten Dämons (5), Fläschchen der zahllosen Armeen (5), Fläschchen der zehntausend Narben (5), Blut von Sargeras" }
entries[127916] = { ["name"] = "Altruis' Erkenntnisse", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"In Azsuna muss es jemanden geben, der um die Säulen der Schöpfung weiß.\"" }
entries[127917] = { ["name"] = "Rezept: Uralter Heiltrank", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die effizientere Herstellung eines uralten Heiltranks.\nBenötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nUralter Heiltrank\nBenutzen: Regeneriert 6000 Gesundheit. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Yserallinensamen (4), Kristallphiole" }
entries[127918] = { ["name"] = "Rezept: Uralter Manatrank", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die effizientere Herstellung eines uralten Manatranks.\nBenötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nUralter Manatrank\nBenutzen: Regeneriert 2000 Mana. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Yserallinensamen (5), Kristallphiole" }
entries[127919] = { ["name"] = "Rezept: Uralter Verjüngungstrank", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die effizientere Herstellung eines uralten Verjüngungstranks.\nBenötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nUralter Verjüngungstrank\nBenutzen: Regeneriert 6000 Gesundheit und 1500 Mana. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Uralter Heiltrank , Uralter Manatrank" }
entries[127920] = { ["name"] = "Rezept: Destillat aus roher Magie", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Destillat aus roher Magie noch effizienter herstellt.\nBenötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nDestillat aus roher Magie\nBenutzen: Auf ex.\nVerkaufspreis:\nBenötigt Aethril (20), Uralter Heiltrank" }
entries[127921] = { ["name"] = "Rezept: Sylvanelixier", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Sylvanelixier effizienter herstellt.\nBenötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nSylvanelixier\nBenutzen: Verwandelt Euch in einen Baum. Ihr und alle Spielercharaktere, die sich in Eurem Schatten ausruhen, werden gut erholt und alle Eure Werte um 10% erhöht.\nVerkaufspreis:\nBenötigt Traumlaub (5), Uralter Heiltrank" }
entries[127922] = { ["name"] = "Rezept: Lawinenelixier", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Lawinenelixier effizienter herstellt.\nBenötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nLawinenelixier\nBenutzen: Wenn Ihr eine lange Strecke fallt, verwandelt Ihr Euch in eine Lawine. Beim Auftreffen fügt Ihr allen Gegnern innerhalb von 5 Metern 1500 Schaden zu. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Fuchsblume (5), Uralter Manatrank" }
entries[127923] = { ["name"] = "Rezept: Skaggldrynk", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Skaggldrynk noch effizienter herstellt.\nBenötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nSkaggldrynk\nBenutzen: Begebt Euch in das Geisterreich und werdet so für 18 Sek. unsichtbar. Funktioniert nicht über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Fjarnskaggl (5), Uralter Manatrank" }
entries[127924] = { ["name"] = "Rezept: Himmelslauftrank", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Himmelslauftrank noch effizienter herstellt.\nBenötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nHimmelslauftrank\nBenutzen: Erhöht die Bewegungsgeschwindigkeit um 150% und lässt den Trinkenden in der Luft schweben. Hält 8 Sek. lang an. Funktioniert nicht über Stufe 50. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose (4), Uralter Verjüngungstrank" }
entries[127925] = { ["name"] = "Rezept: Infernaler Alchemistenstein", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen infernalen Alchemistenstein noch effizienter herstellt.\nBenötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nInfernaler Alchemistenstein\nWird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+ 7 Vielseitigkeit\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 19 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\nBenötigt Alchemie der Verheerten Inseln\n(1)\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:\nBenötigt Infernoschwefel , Teufelswurz (5), Blut von Sargeras (3)" }
entries[127926] = { ["name"] = "Rezept: Trank der tödlichen Anmut", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Trank der tödlichen Anmut noch effizienter herstellt.\nBenötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nTrank der tödlichen Anmut\nBenutzen: Gewährt Euren Angriffen eine Chance, einen Energieblitz auf Euer Ziel zu entfesseln.\n\nWenn Ihr Euch während der gesamten Effektdauer von Gegnern fernhaltet, wird sie um zusätzliche 5 Sek. verlängert. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose , Fjarnskaggl (2), Traumlaub (2), Kristallphiole" }
entries[127927] = { ["name"] = "Rezept: Trank des Alten Krieges", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Trank des Alten Krieges noch effizienter herstellt.\nBenötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nTrank des Alten Krieges\nBenutzen: Beschwört zwei geisterhafte gefallene Krieger, die an Eurer Seite kämpfen. Sie können Eure Nahkampfangriffe und -fähigkeiten imitieren und verursachen damit 1161 Schaden. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose , Fuchsblume (2), Fjarnskaggl (2), Kristallphiole" }
entries[127928] = { ["name"] = "Rezept: Unbeugsamer Trank", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen unbeugsamen Trank noch effizienter herstellt.\nBenötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nUnbeugsamer Trank\nBenutzen: Erhöht Eure Rüstung 25 Sek. lang um 124 . (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose , Aethril (2), Fuchsblume (2), Kristallphiole" }
entries[127929] = { ["name"] = "Rezept: Leywirbeltrank", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Leywirbeltrank noch effizienter herstellt.\nBenötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nLeywirbeltrank\nBenutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu ( 300 * 10) Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose , Aethril (2), Traumlaub (2), Kristallphiole" }
entries[127930] = { ["name"] = "Rezept: Fläschchen des geflüsterten Pakts", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Fläschchen des geflüsterten Pakts noch effizienter herstellt.\nBenötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nFläschchen des geflüsterten Pakts\nBenutzen: Erhöht die Intelligenz 1 Stunde lang um 46 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose (7), Fjarnskaggl (10), Traumlaub (10), Kristallphiole" }
entries[127931] = { ["name"] = "Rezept: Fläschchen des Siebten Dämons", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Fläschchen des Siebten Dämons noch effizienter herstellt.\nBenötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nFläschchen des Siebten Dämons\nBenutzen: Erhöht die Beweglichkeit 1 Stunde lang um 46 . Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Sternlichtrose (7), Fuchsblume (10), Fjarnskaggl (10), Kristallphiole" }
