entries[127988] = { ["name"] = "Käferspray", ["text"] = "Questgegenstand\nBenutzen: Sprüht einen Drogbar mit einem Käfer anlockenden Nebel ein. (5 Sek. Abklingzeit)\n\"Pheromone, die eine tödlich anziehende Wirkung auf Insekten haben.\"" }
