entries[127991] = { ["name"] = "Dämonenschlundfrenzy", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 5288 Gesundheit und ( 1375 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet eine Chance, regelmäßig Salven von Teufelsblitzen abzufeuern, während Ihr angreift.\n\"Die Fische des Tanaandschungels waren schon immer böse. Die dämonische Verderbnis hat sie nur zu richtigen Satansbraten gemacht.\"\nVerkaufspreis:" }
entries[127992] = { ["name"] = "Neuer Rekrut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Altruis der Leidende hat die Tapfersten unter den Illidari herausgefordert, sich Euch anzuschließen. Wer wird dem Ruf folgen?\"" }
entries[127994] = { ["name"] = "Oschi der Dämonenschlundfrenzys", ["text"] = "Wird beim Aufheben gebunden\n\"Die Fische des Tanaandschungels waren schon immer böse. Die dämonische Verderbnis hat sie nur zu richtigen Satansbraten gemacht. Ein Fang, der nur Meisteranglern mit der Hilfe von Nat Pagle gelingt.\"" }
entries[127995] = { ["name"] = "Zurückgelassener Schwarzmarktposten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Ein Gegenstand, der in einer vorangegangenen Auktion versteigert, aber nicht abgeholt wurde. Vorsicht beim Öffnen.\"\n<Zum Öffnen rechtsklicken>" }
