entries[128209] = { ["name"] = "Rezept: Wilde Transmutation", ["text"] = "Rang 1\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen wilde Transmutation herstellt.\nFührt 'Wilde Transmutation' an der Dalaraner Alchemiestation aus.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nBenötigt Leyflammenbrenner, verbesserte Korken, zweikammeriges Mischfläschchen und Präzipitationspulver.\nVerkaufspreis:\nWilde Transmutation\n\"Was werdet Ihr bekommen?\"\nBenötigt Aethril (10), Traumlaub (10), Fuchsblume (10), Fjarnskaggl (10), Sternlichtrose" }
entries[128210] = { ["name"] = "Rezept: Wilde Transmutation", ["text"] = "Rang 2\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine wilde Transmutation ohne Alchemietisch herstellt.\nBenötigt nicht mehr die Dalaraner Alchemiestation.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nWilde Transmutation\n\"Was werdet Ihr bekommen?\"\nBenötigt Aethril (7), Traumlaub (7), Fuchsblume (7), Fjarnskaggl (7), Sternlichtrose" }
entries[128211] = { ["name"] = "Rezept: Wilde Transmutation", ["text"] = "Rang 3\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine wilde Transmutation mit mehreren Effekten herstellt.\nChance auf die Herstellung mehrerer Gegenstände.\nBenötigt Alchemie der Verheerten Inseln\n(1)\nVerkaufspreis:\nWilde Transmutation\n\"Was werdet Ihr bekommen?\"\nBenötigt Aethril (5), Traumlaub (5), Fuchsblume (5), Fjarnskaggl (5), Sternlichtrose" }
