entries[128219] = { ["name"] = "Teufelsgeräucherter Schinken", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 2125 * 20 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Man sollte es nicht für möglich halten, aber die Feldrationen der Eisernen Horde sind noch ekliger geworden.\"\nVerkaufspreis:" }
