entries[128223] = { ["name"] = "Nie versiegendes Styganapilzbräu", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Stellt im Verlauf von 20 Sek. ( 2125 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben. Könnte mit Nebenwirkungen einhergehen. Kann nur in Außengebieten von Draenor konsumiert werden. (20 Min Abklingzeit)" }
