entries[128277] = { ["name"] = "Teufelsblutgronnling des wilden Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nTeufelsblutgronnling des wilden Gladiators : Beschwören oder wieder freigeben\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Einer der Gronnlinge aus dem Tanaandschungel, die von dem von Gul'dan verschuldeten Ausbruch von Teufelsenergie übermannt wurden und nun einen unstillbaren Hunger für Chaos verspüren.\"\nErfolg:\nGladiator: 1. Saison von Warlords\nKategorie:\nHeldentaten" }
entries[128280] = { ["name"] = "Monddornbündel", ["text"] = "Questgegenstand\nBenutzen: Im Wasser eines uralten Mondbrunnens läutern." }
entries[128281] = { ["name"] = "Teufelsblutgronnling des unbändigen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nTeufelsblutgronnling des unbändigen Gladiators : Beschwören oder wieder freigeben\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Einer der Gronnlinge aus dem Tanaandschungel, die von dem von Gul'dan verschuldeten Ausbruch von Teufelsenergie übermannt wurden und nun einen unstillbaren Hunger für Chaos verspüren.\"\nErfolg:\nGladiator: Saison 2 von Warlords\nKategorie:\nHeldentaten" }
entries[128282] = { ["name"] = "Teufelsblutgronnling des kriegstreibenden Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nTeufelsblutgronnling des kriegstreibenden Gladiators : Beschwören oder wieder freigeben\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Einer der Gronnlinge aus dem Tanaandschungel, die von dem von Gul'dan verschuldeten Ausbruch von Teufelsenergie übermannt wurden und nun einen unstillbaren Hunger für Chaos verspüren.\"\nErfolg:\nGladiator: 3. Saison von Warlords\nKategorie:\nHeldentaten" }
entries[128286] = { ["name"] = "Borstenpelz", ["text"] = "Questgegenstand\n\"Ein dicker Pelz aus dichten, rasiermesserscharfen Haaren.\"" }
entries[128287] = { ["name"] = "Zünder", ["text"] = "Questgegenstand\nBenutzen: Detoniert den schweren gilnearischen Sprengstoff. Nehmt vor der Aktivierung einen Sicherheitsabstand ein!" }
entries[128288] = { ["name"] = "Schuppenstachel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand Schwert\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Stärke\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\nKlassen: Krieger\n\"Von hier entspringt die wahre Stärke. Aus tiefen Orten... in der Welt und in Euch selbst.\"\nVerkaufspreis:" }
entries[128289] = { ["name"] = "Schuppe des Erdwächters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Schild\n25 Rüstung\n+1 Stärke\n+3 Intelligenz\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\n\nEisen Artefakt Relikt Slot\nBlut Artefakt Relikt Slot\n\nKlassen: Krieger\nAnlegen: Gewährt die Fähigkeit 'Neltharions Zorn', die Feuer aus Eurem Schild entfesselt und seine Verteidigungseigenschaften stark erhöht.\n\"Es war eine von Neltharions abgeworfenen Schuppen. Sie rettete Magnar das Leben. Der Strahl der Flamme teilte sich um die schwarze Schuppe, doch die Wucht selbst beförderte Magnar aus dem Hort und ließ ihn den Hang des Hochbergs hinunterrollen.\"\nVerkaufspreis:" }
entries[128290] = { ["name"] = "Runenbeschriebener Foliant", ["text"] = "Questgegenstand\n\"In einer Sprache verfasst, die Ihr nicht versteht.\"" }
entries[128291] = { ["name"] = "Übersetzung des runenbeschriebenen Folianten", ["text"] = "Questgegenstand\n\"In einer Sprache verfasst, die Ihr verstehen könnt!\"" }
entries[128292] = { ["name"] = "Klingen des gefallenen Prinzen", ["text"] = "Frostschnitter\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Schwert\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Stärke\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\n\nFrost Artefakt Relikt Slot\nSchatten Artefakt Relikt Slot\n\nKlassen: Todesritter\nAnlegen: Gewährt die Fähigkeit 'Kristallene Schwerter', die schwebende Schwerter herbeiruft, die Eure Gegner durchstoßen.\n\"Wenn meine Zeit gekommen ist, sollst du König sein.\"\nVerkaufspreis:" }
entries[128293] = { ["name"] = "Klingen des gefallenen Prinzen", ["text"] = "Eisbringer\nWird beim Aufheben gebunden\nEinzigartig\nSchildhand Schwert\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+1 Stärke\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\nKlassen: Todesritter\n\"Ich werde Euch der Gerechtigkeit des Grabes zuführen... und die wahre Bedeutung der Furcht lehren.\"" }
entries[128294] = { ["name"] = "Handelsvertrag: Ausgestoßene Arakkoa", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Erhöht die maximale Größe Eures Garnisonslagers auf 1000.\nBenötigt Ausgestoßene Arakkoa\n- Respektvoll\n\"Ein Abkommen zur Sicherung von Versorgungslinien zwischen Eurer Garnison und den verbliebenen ausgestoßenen Arakkoa.\"\nVerkaufspreis:" }
