entries[128301] = { ["name"] = "Schiff: U-Boot", ["text"] = "\"Ein Tauchfahrzeug, das verheerenden Schaden anrichtet. Kann auf Marinemissionen eingesetzt werden.\"" }
entries[128302] = { ["name"] = "Schiff: Schlachtschiff", ["text"] = "\"Ein schnelles, gut gepanzertes Schiff. Kann auf Marinemissionen eingesetzt werden.\"" }
entries[128303] = { ["name"] = "Schiff: Zerstörer", ["text"] = "\"Ein mächtiges Schiff mit großen Kanonen. Kann auf Marinemissionen eingesetzt werden.\"" }
entries[128304] = { ["name"] = "Yserallinensamen", ["text"] = "Handwerksmaterial\n\"Wird von Spielercharakteren gesammelt, die den Beruf Kräuterkunde ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[128305] = { ["name"] = "Havis Horn", ["text"] = "Questgegenstand\nBenutzen: Verursacht Naturschaden. (1 Min Abklingzeit)\n\"Ruft Odyns Macht herbei.\"" }
entries[128306] = { ["name"] = "G'Hanir, der Mutterbaum", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n2 - 3 Schaden Geschwindigkeit 3.60\n(0.7 Schaden pro Sekunde)\n+9 Intelligenz\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nLeben Artefakt Relikt Slot\nFrost Artefakt Relikt Slot\n\nKlassen: Druide\nAnlegen: Gewährt die Fähigkeit 'Essenz von G'Hanir', die den Effekt Eurer anderen Heilzauber um ein großes Maß erhöht.\n\"Am Anfang gab es eine Quelle der Heilung und des Gleichgewichts, einen Ort, an dem alles Leben ruhen und wiederbelebt werden konnte.\"\nVerkaufspreis:" }
entries[128307] = { ["name"] = "Draenische Waffe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Rüstet einen Anhänger mit einer Waffe der Machtstufe 645 aus.\nBringt 10 Anhänger in Eurer Kriegsmeute auf Machtstufe 650.\nVerkaufspreis:" }
entries[128308] = { ["name"] = "Draenisches Rüstungsset", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Rüstet einen Anhänger mit einem vollständigen Rüstungssatz der Machtstufe 645 aus.\nBringt 10 Anhänger in Eurer Kriegsmeute auf Machtstufe 650.\nVerkaufspreis:" }
entries[128309] = { ["name"] = "Splitter von Cyrukh", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick den Splitter von Cyrukh beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[128310] = { ["name"] = "Brennende Klinge", ["text"] = "Spielzeug\nBenutzen: Legt das Banner und die Waffen der Brennenden Klinge an. (1 Stunde Abklingzeit)\n\"Sowohl Banner als auch Waffe von Meistern der Klinge.\"" }
entries[128311] = { ["name"] = "Kohlefaustgronnling", ["text"] = "Reittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nKohlefaustgronnling : Beschwören oder wieder freigeben\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser kleine Gronnling ist dafür bekannt, dass er sich in die Gasthäuser der Garnisonen vorkämpft und Chaos mit den Töpfen und Pfannen anrichtet.\"\nGarnisonsmission:\nBrecher im Doppelpack" }
entries[128312] = { ["name"] = "Elixier des Blitzdenkers", ["text"] = "\"Riecht schwach nach verrottendem Lavendel.\"\nVerkaufspreis:" }
entries[128313] = { ["name"] = "Riesiger Ogervorrat", ["text"] = "Benutzen: Erhaltet 1000 Garnisonsressourcen." }
entries[128314] = { ["name"] = "Vereiste Waffen eines Helden", ["text"] = "Benutzen: Wertet Rüstung und Waffe eines Anhängers um 50 Machtstufen auf.\n\"Die Hinterlassenschaften eines gefallenen Helden von Draenor.\"" }
entries[128315] = { ["name"] = "Medaillon der Legion", ["text"] = "Benutzen: Zerstört das Medaillon und erhöht den Ruf bei den Einwohnern Draenors um 1000.\n\"Jeder hasst die Legion.\"" }
