entries[128320] = { ["name"] = "Verderbter urzeitlicher Obelisk", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert den verderbten Obelisken auf dem Boden. Alle Ziele in der Nähe werden angegriffen.\n\nWirkt nur auf Draenor.\nDie Dauer beträgt 30 Sek. (5 Min Abklingzeit)\n\"Einst war dieser Obelisk eine Macht der Schöpfung, doch er wurde verderbt und dient jetzt einzig der Zerstörung.\"" }
