entries[128402] = { ["name"] = "Schlund der Verdammten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Axt\n3 - 7 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\n+2 Stärke\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nBlut Artefakt Relikt Slot\nSchatten Artefakt Relikt Slot\n\nKlassen: Todesritter\nAnlegen: Gewährt die Fähigkeit 'Schwindsucht', die massiven Schaden verursacht und Gesundheit auf den Träger überträgt.\n\"Der Durst des Schlunds ist unstillbar. Wird ihm nicht mit frischen Opfern gedient, wird er nicht zögern, stattdessen von seinem Herrn zu trinken.\"\nVerkaufspreis:" }
entries[128403] = { ["name"] = "Apokalypse", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Schwert\n3 - 7 Schaden Geschwindigkeit 3.60\n(1.4 Schaden pro Sekunde)\n+2 Stärke\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Meisterschaftswertung um + 2.\n\nFeuer Artefakt Relikt Slot\nSchatten Artefakt Relikt Slot\n\nKlassen: Todesritter\nAnlegen: Gewährt die Fähigkeit 'Apokalypse', die Streiter aus Eurer Armee der Toten beschwört, die für Euch kämpfen. (Procchance: 5%, 10Min. Abklingzeit)\n\"Sie soll Zerstörung und Krieg säen. Hunger und Tod. Sie soll mit Macht locken und dann allem Leben ein Ende setzen.\"\nVerkaufspreis:" }
entries[128404] = { ["name"] = "Helbrims Spezial", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Trinkt die fermentierte Essenz von Teufelsenergie. Erhöht den verursachten Schaden gegen Dämonen 10 Min. lang um 10%. Funktioniert nicht bei Spielercharakteren über Stufe 49. (3 Sek. Abklingzeit)\n\"Ziemlich stark.\"" }
