entries[128475] = { ["name"] = "Mächtige Verstärkungsrune", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erhöht Eure Stärke, Beweglichkeit oder Intelligenz (abhängig von Eurer aktuellen Spezialisierung) 1 Stunde lang um 8 . Verstärkungsrune. Kann nicht von Charakteren über Stufe 49 verwendet werden. (1 Min Abklingzeit)\nBenötigt Vol'jins Kopfjäger\n- Ehrfürchtig\nVerkaufspreis:" }
entries[128476] = { ["name"] = "Reißzähne des Verschlingers", ["text"] = "Blutreißer\nWird beim Aufheben gebunden\nEinzigartig\nWaffenhand Dolch\n1 - 3 Schaden Geschwindigkeit 1.80\n(1.1 Schaden pro Sekunde)\n+1 Beweglichkeit\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 1.\n\nTeufel Artefakt Relikt Slot\nSchatten Artefakt Relikt Slot\n\nKlassen: Schurke\nAnlegen: Gewährt die Fähigkeit 'Blutschlunds Biss', die massiven Schaden verursacht und das Ziel verlangsamt.\n\"Der Biss des Hundes ist noch immer präsent, all die Jahre nach seinem Tod. Für ein derart primitives Werkzeug ist es erstaunlich wirksam und geschmeidig.\"\nVerkaufspreis:" }
entries[128477] = { ["name"] = "Wildes Tigerjunges", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\n80 ( 80)\nBenötigt Die Säbelzahnpirscher\n- Respektvoll" }
