entries[128480] = { ["name"] = "Stachelhölleneber", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nStachelhölleneber : Beschwören oder wieder freigeben\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Vol'jins Kopfjäger\n- Ehrfürchtig\nVerkaufspreis:\n\"Die einzige Quelle für die überaus seltene Kochzutat: verfluchter Schinken\"\nVerkäufer:\nZ'tenga der Wanderer\nZone:\nTanaandschungel\nFraktion:\nDie Säbelzahnpirscher - Ehrfürchtig\nKosten:\n5.000" }
